(window.webpackJsonp=window.webpackJsonp||[]).push([[141],{467:function(e,t,r){"use strict";r.r(t);var s=r(33),a=Object(s.a)({},function(){var e=this,t=e.$createElement,r=e._self._c||t;return r("ContentSlotsDistributor",{attrs:{"slot-key":e.$parent.slotKey}},[r("h1",{attrs:{id:"laserskarprincipen"}},[r("a",{staticClass:"header-anchor",attrs:{href:"#laserskarprincipen","aria-hidden":"true"}},[e._v("#")]),e._v(" Laserskärprincipen")]),e._v(" "),r("p",[e._v("Laserstrålen är en ljusstråle som består av elektromag­netisk strålning med bestämd och konstant våglängd. Strålen som har stor effekttäthet kan fokuseras till en liten punkt på arbetsstycket med så hög temperatur att materialet smälter. Lasermediet i denna lasertyp är en blandning av koldioxid, helium och nitrogen. Som namnet antyder är det koldioxiden som utgör den genererande gasen, medan helium och nitrogen till­sätts för att öka effektiviteten i processen. Själva laserprocessen erhålls genom att tillföra elektrisk energi (högspänning) till laserröret.")]),e._v(" "),r("p",[e._v("Det finns olika typer av skärlasrar, mest vanlig är CO 2-laser som lämpar sig bäst vid skärning i metalliska material. Vid skärning i stål används ofta ren oxygen som skärgas. Gasen har till uppgift att blåsa bort det smälta materialet, men även skydda linsen mot sprut och rök, samt i de fall oxygen används som skärgas bidrar till skärprocessen genom det energitillskott som fås vid oxidationen av materialet. Energitillskottet medger höga skärhastigheter i framför allt tunt material.")]),e._v(" "),r("p",[r("img",{attrs:{src:"https://lernia.itslearning.com/data/1821/C2567/A8/A8%20bild%2025.JPG",alt:""}})])])},[],!1,null,null,null);t.default=a.exports}}]);